{#- Code generated by packages/kit-compose/src/server-organisms.ts from packages/compose-gen/specs (compose-gen organism emitters on kit-compose). DO NOT EDIT.
    Source: packages/compose-gen/specs/patterns/media-frame.json
    A picture in a fixed ratio that follows the theme. `src` is the picture of the light theme, `darkSrc` the one of the dark theme (without it the dark theme shows `src`). Without both (an empty string counts as none) it shows the built-in neutral placeholders (base64 data URIs, one light and one dark), so a page can be laid out before it has pictures; the placeholder is decorative (`alt` is empty), stands in for a real `src` and is switched by the theme token. A real picture gets `alt` and loads lazily. `ratio` comes from the recipe; the corners are the plain theme radius. `srcset` lists sizes of `src` (written by an export, e.g. WebP 960w / 1280w / 1920w) and `sizes` says how wide the picture is shown, so the browser picks a size; the dark picture takes the srcset only when it is `src` (no `darkSrc`).
    Props (p): alt, src, darkSrc, ratio, srcset, sizes, className. -#}
{%- set k_PLACEHOLDER = {'light': 'data:image/svg+xml;base64,', 'dark': 'data:image/svg+xml;base64,'} -%}
{%- set v_alt = (p.alt ?? null) -%}
{%- set v_src = (p.src ?? null) -%}
{%- set v_darkSrc = (p.darkSrc ?? null) -%}
{%- set v_ratio = (p.ratio ?? '16/9') -%}
{%- set v_srcset = (p.srcset ?? null) -%}
{%- set v_sizes = (p.sizes ?? '100vw') -%}
{%- set v_lightSrc = (og_t(v_src) ? v_src : og_at(k_PLACEHOLDER, 'light')) -%}
{%- set v_nightSrc = (og_t(v_darkSrc) ? v_darkSrc : (og_t(v_src) ? v_src : og_at(k_PLACEHOLDER, 'dark'))) -%}
{%- set v_shownAlt = (og_t(v_src) ? v_alt : '') -%}
{%- set v_loadHint = (og_t(v_src) ? 'lazy' : null) -%}
{%- set v_decodeHint = (og_t(v_src) ? 'async' : null) -%}
{%- set v_lightSet = (og_t(og_and([v_src, v_srcset])) ? v_srcset : null) -%}
{%- set v_nightSet = (og_t(v_darkSrc) ? null : v_lightSet) -%}
{%- set v_lightSizes = (og_t(v_lightSet) ? v_sizes : null) -%}
{%- set v_nightSizes = (og_t(v_nightSet) ? v_sizes : null) -%}
